using namespace std;
​
int main() {
    int rows, cols;
    cin >> rows >> cols;
​
    vector<vector<int>> matrix(rows, vector<int>(cols));
    unordered_map<int, vector<pair<int, int>>> positionMap;
​
    // 读取矩阵数据并记录每个数字出现的位置
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            cin >> matrix[i][j];
            positionMap[matrix[i][j]].emplace_back(i, j);
        }
    }
​
    vector<vector<int>> result(rows, vector<int>(cols, -1));
​
    // 遍历矩阵，计算到最近相同元素的曼哈顿距离
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            int currentNum = matrix[i][j];
​
            // 如果该数字出现多次，则计算最小距离
            if (positionMap[currentNum].size() > 1) {
                int minDistance = INT_MAX;
                for (const auto& [x, y] : positionMap[currentNum]) {
                    int distance = abs(x - i) + abs(y - j);
                    if (distance > 0) {  // 排除自身
                        minDistance = min(minDistance, distance);
                    }
                }
                result[i][j] = minDistance;
            }
        }
    }
​
    // 格式化输出
    cout << "[";
    for (int i = 0; i < rows; i++) {
        cout << "[";
        for (int j = 0; j < cols; j++) {
            cout << result[i][j] << (j < cols - 1 ? ", " : "");
        }
        cout << "]" << (i < rows - 1 ? ", " : "");
    }
    cout << "]";
​
    return 0;
}
