import java.util.*;
​
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] matrix = new int[rows][cols];
        Map<Integer, List<int[]>> positionMap = new HashMap<>();
​
        // 读取矩阵数据并记录每个数字出现的位置
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
                positionMap.computeIfAbsent(matrix[i][j], k -> new ArrayList<>()).add(new int[]{i, j});
            }
        }
​
        int[][] result = new int[rows][cols];
        for (int[] row : result) {
            Arrays.fill(row, -1);
        }
​
        // 遍历矩阵，计算到最近相同元素的曼哈顿距离
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int currentNum = matrix[i][j];
​
                // 如果该数字出现多次，则计算最小距离
                if (positionMap.get(currentNum).size() > 1) {
                    int minDistance = Integer.MAX_VALUE;
                    for (int[] pos : positionMap.get(currentNum)) {
                        int x = pos[0], y = pos[1];
                        int distance = Math.abs(x - i) + Math.abs(y - j);
                        if (distance > 0) {  // 排除自身
                            minDistance = Math.min(minDistance, distance);
                        }
                    }
                    result[i][j] = minDistance;
                }
            }
        }
​
        // 格式化输出
        System.out.print("[");
        for (int i = 0; i < rows; i++) {
            System.out.print("[");
            for (int j = 0; j < cols; j++) {
                System.out.print(result[i][j]);
                if (j < cols - 1) System.out.print(", ");
            }
            System.out.print("]");
            if (i < rows - 1) System.out.print(", ");
        }
        System.out.println("]");
    }
}
