const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let input = [];
rl.on("line", (line) => {
    input.push(line);
}).on("close", () => {
    let rows = parseInt(input[0]);  // 读取行数
    let cols = parseInt(input[1]);  // 读取列数
​
    let matrix = [];
    let positionMap = new Map();
​
    // 读取矩阵数据并记录每个数字出现的位置
    for (let i = 2; i < 2 + rows; i++) {
        let row = input[i].split(" ").map(Number);
        matrix.push(row);
        row.forEach((num, j) => {
            if (!positionMap.has(num)) {
                positionMap.set(num, []);
            }
            positionMap.get(num).push([i - 2, j]); // 记录坐标
        });
    }
​
    let result = Array.from({ length: rows }, () => Array(cols).fill(-1));
​
    // 遍历矩阵，计算到最近相同元素的曼哈顿距离
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            let currentNum = matrix[i][j];
​
            if (positionMap.get(currentNum).length > 1) {
                let minDistance = Infinity;
                for (let [x, y] of positionMap.get(currentNum)) {
                    let distance = Math.abs(x - i) + Math.abs(y - j);
                    if (distance > 0) { // 排除自身
                        minDistance = Math.min(minDistance, distance);
                    }
                }
                result[i][j] = minDistance;
            }
        }
    }
​
    // 格式化输出
    console.log("[");
    console.log(result.map(row => "  [" + row.join(", ") + "]").join(",\n"));
    console.log("]");
});
