package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
    "math"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取行数和列数
    scanner.Scan()
    rows, _ := strconv.Atoi(scanner.Text())
    scanner.Scan()
    cols, _ := strconv.Atoi(scanner.Text())
​
    // 读取矩阵数据并记录每个数字出现的位置
    matrix := make([][]int, rows)
    positionMap := make(map[int][][]int)
​
    for i := 0; i < rows; i++ {
        scanner.Scan()
        line := strings.Fields(scanner.Text())
        matrix[i] = make([]int, cols)
        for j := 0; j < cols; j++ {
            matrix[i][j], _ = strconv.Atoi(line[j])
            positionMap[matrix[i][j]] = append(positionMap[matrix[i][j]], []int{i, j})
        }
    }
​
    // 结果矩阵初始化
    result := make([][]int, rows)
    for i := range result {
        result[i] = make([]int, cols)
        for j := range result[i] {
            result[i][j] = -1
        }
    }
​
    // 遍历矩阵，计算到最近相同元素的曼哈顿距离
    for i := 0; i < rows; i++ {
        for j := 0; j < cols; j++ {
            currentNum := matrix[i][j]
​
            // 如果该数字出现多次，则计算最小距离
            if len(positionMap[currentNum]) > 1 {
                minDistance := math.MaxInt32
                for _, pos := range positionMap[currentNum] {
                    x, y := pos[0], pos[1]
                    if x != i || y != j { // 排除自身
                        distance := abs(x-i) + abs(y-j)
                        if distance < minDistance {
                            minDistance = distance
                        }
                    }
                }
                result[i][j] = minDistance
            }
        }
    }
​
    // 格式化输出（紧凑格式）
    fmt.Print("[")
    for i, row := range result {
        fmt.Print("[")
        for j, val := range row {
            fmt.Print(val)
            if j < cols-1 {
                fmt.Print(", ")
            }
        }
        fmt.Print("]")
        if i < rows-1 {
            fmt.Print(", ")
        }
    }
    fmt.Println("]")
}
